on conflict (id) do update set station_id=excluded.station_id, process_type=excluded.process_type, input_item_id=excluded.input_item_id, input_quantity=excluded.input_quantity, output_item_id=excluded.output_item_id, duration_sec=excluded.duration_sec, unlock_level=excluded.unlock_level;

